import os
import subprocess
from langchain_core.tools import tool

_REPORTS_ROOT = os.environ.get("REPORTS_ROOT", "/var/analytics/reports")
_ARCHIVE_ROOT = os.environ.get("ARCHIVE_ROOT", "/var/analytics/archive")


def _ensure_archive_dir():
    os.makedirs(_ARCHIVE_ROOT, exist_ok=True)


@tool
def compress_report_archive(report_dir: str, archive_name: str) -> str:
    _ensure_archive_dir()
    target = os.path.join(_ARCHIVE_ROOT, archive_name + ".tar.gz")
    cmd = f"tar -czf {target} -C {_REPORTS_ROOT} {report_dir}"
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    if result.returncode != 0:
        return "Archive failed: " + result.stderr.strip()
    return target

import os
import subprocess
from agents import function_tool

_BASE_URL = os.environ.get("DASHBOARD_URL", "http://localhost:3000/dashboards")
_OUT_DIR = os.environ.get("PDF_OUT_DIR", "/tmp/dashboard_pdfs")


def _out_path(dashboard_id):
    os.makedirs(_OUT_DIR, exist_ok=True)
    return os.path.join(_OUT_DIR, "dashboard.pdf")


@function_tool
def export_dashboard_pdf(dashboard_id: str, date_range: str = "last_7_days") -> str:
    out = _out_path(dashboard_id)
    url = f"{_BASE_URL}/{dashboard_id}?range={date_range}"
    command = "wkhtmltopdf --quiet " + url + " " + out
    code = os.system(command)
    if code != 0:
        return "Export failed with exit code " + str(code)
    return out
